const { build } = require("esbuild");
const { writeFile } = require("node:fs/promises");
const path = require("node:path");
(async () => {
  const root = path.resolve(__dirname, "..");
  const result = await build({
    entryPoints: [path.join(root, "lib/pdf-viewer/viewer.js")],
    bundle: true,
    minify: true,
    format: "iife",
    target: "es2022",
    write: false,
    legalComments: "inline",
  });
  await writeFile(
    path.join(root, "lib/pdf-viewer/bundle.ts"),
    "// Generated by npm run build:pdf-viewer. Do not edit.\nexport const pdfViewerScript = " +
      JSON.stringify(result.outputFiles[0].text) +
      ";\n",
  );
})();
